function setLanguage(language) {
  activeLanguage = languages.some((item) => item.code === language) ? language : "en";
  localStorage.setItem(LANGUAGE_KEY, activeLanguage);
  render();
}

function getActiveLanguage() {
  return activeLanguage;
}

function languageName(code) {
  return languages.find((item) => item.code === code)?.label || code;
}

function t(value) {
  return translateText(value);
}

function translateText(value) {
  const text = String(value ?? "");
  if (activeLanguage === "en" || !text.trim()) return text;
  const leading = text.match(/^\s*/)?.[0] || "";
  const trailing = text.match(/\s*$/)?.[0] || "";
  const trimmed = text.trim();
  const translated = translateTrimmed(trimmed);
  return `${leading}${translated}${trailing}`;
}

function translateTrimmed(text) {
  const dictionary = translations[activeLanguage] || {};
  if (dictionary[text]) return dictionary[text];
  let translated = text;
  for (const [source, target] of phraseTranslations[activeLanguage] || []) {
    translated = translated.split(source).join(target);
  }
  for (const [source, target] of Object.entries(dictionary)) {
    if (monthNames.includes(source)) translated = translated.split(source).join(target);
  }
  return translated;
}

function applyDocumentLanguage() {
  document.documentElement.lang = activeLanguage;
  document.title = activeLanguage === "en" ? "ModernLam Accounting Prototype" : translateTrimmed("ModernLam Accounting Prototype");
}

function translateDom(root = document.body) {
  applyDocumentLanguage();
  if (activeLanguage === "en" || !root) return;
  const skippedTextParents = new Set(["SCRIPT", "STYLE", "TEXTAREA"]);
  const textNodes = [];
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
    acceptNode(node) {
      if (!node.nodeValue.trim()) return NodeFilter.FILTER_REJECT;
      if (!node.parentElement || skippedTextParents.has(node.parentElement.tagName)) return NodeFilter.FILTER_REJECT;
      return NodeFilter.FILTER_ACCEPT;
    },
  });
  while (walker.nextNode()) textNodes.push(walker.currentNode);
  textNodes.forEach((node) => {
    const translated = translateText(node.nodeValue);
    if (translated !== node.nodeValue) node.nodeValue = translated;
  });
  root.querySelectorAll("[title], [placeholder], [aria-label], [alt]").forEach((element) => {
    ["title", "placeholder", "aria-label", "alt"].forEach((attribute) => {
      if (!element.hasAttribute(attribute)) return;
      const translated = translateText(element.getAttribute(attribute));
      if (translated !== element.getAttribute(attribute)) element.setAttribute(attribute, translated);
    });
  });
}
